   214  FLAC__bool do_major_operation__append(FLAC__Metadata_Chain *chain, const CommandLineOptions *options)
   215  {
   216          FLAC__byte header[FLAC__STREAM_METADATA_HEADER_LENGTH];
   217          FLAC__byte *buffer;
   218          FLAC__uint32 buffer_size, num_objects = 0, i, append_after = UINT32_MAX;
   219          FLAC__StreamMetadata *object;
   220          FLAC__Metadata_Iterator *iterator = 0;
   221          FLAC__bool has_vorbiscomment = false;
   222
   223          /* First, find out after which block appending should take place */
   224          for(i = 0; i < options->args.num_arguments; i++) {
   225                  if(options->args.arguments[i].type == ARG__BLOCK_NUMBER) {
   226                          if(append_after != UINT32_MAX || options->args.arguments[i].value.block_number.num_entries > 1) {
   227                                  flac_fprintf(stderr, "ERROR: more than one block number specified with --append\n");
   228                                  return false;
   229                          }
   230                          append_after = options->args.arguments[i].value.block_number.entries[0];
   231                  }
   232          }
   233
   234          iterator = FLAC__metadata_iterator_new();
   235
   236          if(0 == iterator)
   237                  die("out of memory allocating iterator");
   238
   239          FLAC__metadata_iterator_init(iterator, chain);
   240
   241          /* Find out whether there is already a vorbis comment block present */
   242          do {
   243                  FLAC__MetadataType type = FLAC__metadata_iterator_get_block_type(iterator);
   244                  if(type == FLAC__METADATA_TYPE_VORBIS_COMMENT)
   245                          has_vorbiscomment = true;
   246          }
   247          while(FLAC__metadata_iterator_next(iterator));
   248
   249          /* Reset iterator */
   250          FLAC__metadata_iterator_init(iterator, chain);
   251
   252          /* Go to requested block */
   253          for(i = 0; i < append_after; i++) {
   254                  if(!FLAC__metadata_iterator_next(iterator))
   255                          break;
   256          }
   257
   258  #ifdef _WIN32
   259          _setmode(fileno(stdin),_O_BINARY);
   260  #endif
   261
   262          /* Read header from stdin */
   263          while(fread(header, 1, FLAC__STREAM_METADATA_HEADER_LENGTH, stdin) == FLAC__STREAM_METADATA_HEADER_LENGTH) {
   264
   265                  buffer_size = ((FLAC__uint32)(header[1]) << 16) + ((FLAC__uint32)(header[2]) << 8) + header[3];
   266                  buffer = safe_malloc_(buffer_size + FLAC__STREAM_METADATA_HEADER_LENGTH);
   267                  memcpy(buffer, header, FLAC__STREAM_METADATA_HEADER_LENGTH);
   268
   269                  num_objects++;
   270
   271                  if(fread(buffer+FLAC__STREAM_METADATA_HEADER_LENGTH, 1, buffer_size, stdin) < buffer_size) {
   272                          flac_fprintf(stderr, "ERROR: couldn't read metadata block #%u from stdin\n",(num_objects));
   273                          free(buffer);
   274                          FLAC__metadata_iterator_delete(iterator);
   275                          return false;
   276                  }
   277
   278                  if((object = FLAC__metadata_object_set_raw(buffer, buffer_size + FLAC__STREAM_METADATA_HEADER_LENGTH)) == NULL) {
   279                          flac_fprintf(stderr, "ERROR: couldn't parse supplied metadata block #%u\n",(num_objects));
   280                          free(buffer);
   281                          FLAC__metadata_iterator_delete(iterator);
   282                          return false;
   283                  }
   284                  free(buffer);
   285
   286                  if(has_vorbiscomment && object->type == FLAC__METADATA_TYPE_VORBIS_COMMENT) {
   287                          flac_fprintf(stderr, "ERROR: can't add another vorbis comment block to file, it already has one\n");
   288                          FLAC__metadata_object_delete(object);
   289                          FLAC__metadata_iterator_delete(iterator);
   290                          return false;
   291                  }
   292
   293
   294                  if(object->type == FLAC__METADATA_TYPE_STREAMINFO) {
   295                          flac_fprintf(stderr, "ERROR: can't add streaminfo to file\n");
   296                          FLAC__metadata_object_delete(object);
   297                          FLAC__metadata_iterator_delete(iterator);
   298                          return false;
   299                  }
   300
   301                  if(object->type == FLAC__METADATA_TYPE_SEEKTABLE) {
   302                          flac_fprintf(stderr, "ERROR: can't add seektable to file, please use --add-seekpoint instead\n");
   303                          FLAC__metadata_object_delete(object);
   304                          FLAC__metadata_iterator_delete(iterator);
   305                          return false;
   306                  }
   307
   308                  if(!FLAC__metadata_iterator_insert_block_after(iterator, object)) {
   309                          flac_fprintf(stderr, "ERROR: couldn't add supplied metadata block #%u to file\n",(num_objects));
   310                          FLAC__metadata_object_delete(object);
   311                          FLAC__metadata_iterator_delete(iterator);
   312                          return false;
   313                  }
   314                  /* Now check whether what type of block was added */
   315                  {
   316                          FLAC__MetadataType type = FLAC__metadata_iterator_get_block_type(iterator);
   317                          if(type == FLAC__METADATA_TYPE_VORBIS_COMMENT)
   318                                  has_vorbiscomment = true;
   319                  }
   320          }
   321
   322  #ifdef _WIN32
   323          _setmode(fileno(stdin),_O_TEXT);
   324  #endif
   325
   326          if(num_objects == 0)
   327                  flac_fprintf(stderr, "ERROR: unable to find a metadata block in the supplied input\n");
   328
   329          FLAC__metadata_iterator_delete(iterator);
   330
   331          return true;
   332  }
