   334  FLAC__bool do_major_operation__remove(FLAC__Metadata_Chain *chain, const CommandLineOptions *options)
   335  {
   336          FLAC__Metadata_Iterator *iterator = FLAC__metadata_iterator_new();
   337          FLAC__bool ok = true;
   338          unsigned block_number;
   339
   340          if(0 == iterator)
   341                  die("out of memory allocating iterator");
   342
   343          FLAC__metadata_iterator_init(iterator, chain);
   344
   345          block_number = 0;
   346          while(ok && FLAC__metadata_iterator_next(iterator)) {
   347                  block_number++;
   348                  if(passes_filter(options, FLAC__metadata_iterator_get_block(iterator), block_number)) {
   349                          ok &= FLAC__metadata_iterator_delete_block(iterator, options->use_padding);
   350                          if(options->use_padding)
   351                                  ok &= FLAC__metadata_iterator_next(iterator);
   352                  }
   353          }
   354
   355          FLAC__metadata_iterator_delete(iterator);
   356
   357          return ok;
   358  }
